		FROM memo_tree
	`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	memos := make([]deleteUserMemoRef, 0)
	for rows.Next() {
		var memo deleteUserMemoRef
		if err := rows.Scan(&memo.ID, &memo.UID); err != nil {
			return nil, err
		}
